template.t:
            // Array de vehículos generado dinámicamente desde Odoo
            var vehiculos = [
                
                    
                        {"name": "", "lat": , "lon": },
                    
                
            ];

            // Inicializa el mapa
            var map = L.map('map').setView([23.1136, -82.3666], 11);

            L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                maxZoom: 19,
                attribution: '&copy; OpenStreetMap'
            }).addTo(map);

            // Crear marcadores
            vehiculos.forEach(function(auto){
                L.marker([auto.lat, auto.lon])
                    .addTo(map)
                    .bindPopup(auto.name);
            });

            // Centrar automáticamente según todos los vehículos
            if (vehiculos.length > 0) {
                var bounds = vehiculos.map(v => [v.lat, v.lon]);
                map.fitBounds(bounds, {padding: [50, 50]});
            }
